<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { reportsApi, type ExportFormat } from '@/api/reports'

const route = useRoute(), router = useRouter(), id = String(route.params.id)
const report = ref<any>(null), content = ref(''), savedContent = ref(''), versions = ref<any[]>([]), saving = ref(false), citation = ref<any>(null), exportJob = ref<any>(null), rewriting = ref(false)
let autosaveTimer: ReturnType<typeof setTimeout> | undefined
const outline = computed<Array<{ level: number; title: string; index: number }>>(() => content.value.split('\n').map((line, index) => ({ line, index, match: line.match(/^(#{1,3})\s+(.+)/) })).filter(x => x.match).map(x => ({ level: Number(x.match![1].length), title: String(x.match![2]), index: Number(x.index) })))
const dirty = computed(() => content.value !== savedContent.value)
const evidence = computed(() => (report.value?.current_version.citations || []).map((item: any, index: number) => ({ ...item, number: index + 1 })))
async function load() { report.value = await reportsApi.detail(id); content.value = report.value.current_version.content_markdown; savedContent.value = content.value; versions.value = await reportsApi.versions(id) }
async function save(silent = false) { if (!dirty.value || saving.value) return; saving.value = true; try { const result = await reportsApi.saveVersion(id, { content_markdown: content.value, structured_content: report.value.current_version.structured_content || {}, citation_content_ids: report.value.current_version.citations.map((c: any) => c.content_id) }); report.value.current_version = { ...report.value.current_version, id: result.id, version_number: result.version_number, content_markdown: content.value, citations: result.citations }; savedContent.value = content.value; versions.value = await reportsApi.versions(id); if (!silent) ElMessage.success(`已保存版本 v${result.version_number}`) } finally { saving.value = false } }
watch(content, () => { clearTimeout(autosaveTimer); autosaveTimer = setTimeout(() => void save(true), 1400) })
async function restore(version: any) { await reportsApi.restore(id, version.id); await load(); ElMessage.success(`已恢复到版本 v${version.version_number}`) }
async function rewrite(instruction: string) { const textarea = document.querySelector<HTMLTextAreaElement>('.editor-textarea'); if (!textarea) return; const start = textarea.selectionStart, end = textarea.selectionEnd; const selected = content.value.slice(start, end); if (!selected) return ElMessage.warning('请先选择需要改写的文字'); rewriting.value = true; try { const result = await reportsApi.rewrite(id, selected, instruction); content.value = content.value.slice(0, start) + result.text + content.value.slice(end) } finally { rewriting.value = false } }
async function startExport(format: ExportFormat) { await save(true); exportJob.value = await reportsApi.export(id, format); if (exportJob.value.status === 'ready') download(exportJob.value.id); else ElMessage.error(exportJob.value.error_message || '导出失败') }
async function retry() { exportJob.value = await reportsApi.retry(exportJob.value.id); if (exportJob.value.status === 'ready') download(exportJob.value.id) }
function download(exportId: string) { window.open(reportsApi.downloadUrl(exportId), '_blank') }
function indent(level: number) { return `${10 + (level - 1) * 13}px` }
function jump(line: number) { const area = document.querySelector<HTMLTextAreaElement>('.editor-textarea'); if (!area) return; area.focus(); area.setSelectionRange(Number(content.value.split('\n').slice(0, line).join('\n').length), content.value.length) }
onMounted(load); onBeforeUnmount(() => clearTimeout(autosaveTimer))
</script>
<template><main v-if="report" class="editor-page"><header><button title="返回报告中心" @click="router.push('/reports')"><el-icon><ArrowLeft /></el-icon></button><input v-model="report.title" @change="reportsApi.update(id,{title:report.title})"/><span :class="{dirty}">{{saving?'正在保存':dirty?'等待自动保存':`已保存 · v${report.current_version.version_number}`}}</span><el-dropdown @command="startExport"><button class="export"><el-icon><Download /></el-icon>导出</button><template #dropdown><el-dropdown-menu><el-dropdown-item command="markdown">Markdown</el-dropdown-item><el-dropdown-item command="html">HTML</el-dropdown-item><el-dropdown-item command="docx">Word</el-dropdown-item><el-dropdown-item command="pdf">PDF</el-dropdown-item></el-dropdown-menu></template></el-dropdown><button class="save" :disabled="!dirty" @click="save(false)"><el-icon><Check /></el-icon>保存</button></header>
<section class="workspace"><aside class="outline"><small>目录</small><nav><button v-for="item in outline" :key="`${item.index}-${item.title}`" :style="{paddingLeft:indent(item.level)}" @click="jump(item.index)">{{item.title}}</button></nav><div class="versions"><small>版本历史</small><button v-for="v in versions" :key="v.id" :class="{active:v.id===report.current_version.id}" @click="restore(v)"><span>v{{v.version_number}}</span><time>{{new Date(v.created_at).toLocaleString()}}</time></button></div></aside>
<section class="document"><div class="paper"><div class="paper-meta">{{report.report_type.toUpperCase()}} / INFOPULSE</div><textarea v-model="content" class="editor-textarea" spellcheck="false" aria-label="报告 Markdown 编辑器"></textarea></div></section>
<aside class="evidence"><small>来源引用 · {{evidence.length}}</small><article v-for="c in evidence" :key="c.content_id" @click="citation=c"><b>[{{c.number}}] {{c.title}}</b><span>{{c.source}}</span><p>{{c.quote}}</p></article><div v-if="!evidence.length" class="no-evidence">此报告尚未导入来源。事实结论应先从事件、搜索、收藏、AI 分析或 Agent 引入证据。</div><div class="rewrite"><small>AI 改写</small><button :disabled="rewriting" @click="rewrite('压缩表达，保留全部事实和引用编号')">精简</button><button :disabled="rewriting" @click="rewrite('改写为适合领导简报的专业表达，保留全部事实和引用编号')">领导简报</button><button :disabled="rewriting" @click="rewrite('改善段落结构与可读性，保留全部事实和引用编号')">优化结构</button></div><div v-if="exportJob?.status==='failed'" class="export-error"><p>{{exportJob.error_message}}</p><button @click="retry">重试导出</button></div></aside></section>
<el-drawer v-model="citation" title="来源引用" size="min(480px,92%)"><template v-if="citation"><h3>{{citation.title}}</h3><blockquote>{{citation.quote}}</blockquote><p>{{citation.source}}</p><a :href="citation.url" target="_blank" rel="noopener">打开原始来源</a></template></el-drawer></main>
<main v-else class="loading" v-loading="true"></main></template>
<style scoped>.editor-page{height:100vh;display:grid;grid-template-rows:58px 1fr;color:#17231f;background:#e9eeec}.editor-page>header{padding:0 14px;display:flex;align-items:center;gap:10px;border-bottom:1px solid #cbd6d2;background:#fff}.editor-page>header>button{height:34px;border:1px solid #d0dad6;border-radius:4px;background:#fff}.editor-page>header>input{min-width:0;flex:1;border:0;outline:0;font-size:16px;font-weight:700}.editor-page>header>span{color:#70817a;font-size:11px}.editor-page>header>span.dirty{color:#b06c20}.editor-page .export,.editor-page .save{padding:0 12px;display:flex;align-items:center;gap:5px}.editor-page .save{color:white;background:#19312a}.workspace{min-height:0;display:grid;grid-template-columns:220px minmax(420px,1fr) 300px}.outline,.evidence{min-height:0;padding:18px 12px;overflow:auto;background:#f8faf9}.outline{border-right:1px solid #cbd6d2}.evidence{border-left:1px solid #cbd6d2}.outline>small,.evidence>small,.rewrite small,.versions>small{display:block;margin:0 8px 10px;color:#647770;font-size:10px;font-weight:800;text-transform:uppercase}.outline nav{display:grid}.outline nav button{min-height:32px;overflow:hidden;border:0;text-align:left;text-overflow:ellipsis;white-space:nowrap;background:transparent}.versions{margin-top:24px;padding-top:18px;border-top:1px solid #d8e1dd}.versions button{width:100%;padding:8px;border:0;display:flex;justify-content:space-between;text-align:left;background:transparent}.versions button.active{background:#e3eeea}.versions time{color:#7a8a84;font-size:9px}.document{overflow:auto;padding:34px clamp(20px,4vw,60px)}.paper{width:min(820px,100%);min-height:1050px;margin:0 auto;padding:54px 64px;background:#fff;box-shadow:0 8px 28px rgba(27,52,44,.09)}.paper-meta{padding-bottom:18px;border-bottom:2px solid #167f76;color:#167f76;font-size:9px;font-weight:800}.editor-textarea{width:100%;min-height:940px;margin-top:24px;resize:none;border:0;outline:0;color:#1e2d28;background:transparent;font:15px/1.8 "Microsoft YaHei",sans-serif}.evidence article{padding:12px 8px;border-top:1px solid #dbe3df;cursor:pointer}.evidence article b,.evidence article span{display:block}.evidence article b{font-size:12px;line-height:1.5}.evidence article span{margin-top:5px;color:#168078;font-size:10px}.evidence article p{margin:7px 0 0;display:-webkit-box;overflow:hidden;color:#75857f;font-size:11px;-webkit-line-clamp:3;-webkit-box-orient:vertical}.no-evidence{padding:16px 8px;color:#778780;font-size:12px;line-height:1.6}.rewrite{margin-top:22px;padding-top:18px;border-top:1px solid #d8e1dd}.rewrite button{margin:0 5px 6px 0;padding:7px 9px;border:1px solid #cbd7d2;border-radius:4px;background:white}.export-error{padding:10px;color:#9d3535;background:#faeceb}.export-error button{border:0;color:white;background:#b74545}.loading{height:100vh}@media(max-width:900px){.workspace{grid-template-columns:170px 1fr}.evidence{display:none}.paper{padding:38px}}@media(max-width:650px){.editor-page{height:calc(100vh - 56px)}.editor-page>header>span,.editor-page .export{display:none}.workspace{grid-template-columns:1fr}.outline{display:none}.document{padding:12px}.paper{min-height:100%;padding:28px 20px}.editor-textarea{min-height:calc(100vh - 180px)}}</style>
